        <el-form-item v-if="!supplier && current.status==='submitted' && current.price_adjustment_requires_reason" label="调价原因（必填）"><el-input v-model="priceReason" placeholder="说明已集货后的价格调整原因" :disabled="busy"/></el-form-item>
