          <el-descriptions-item label="到港时间">{{ logisticsDate(current.logistics_dates?.arrived_port_at) }}</el-descriptions-item>
          <el-descriptions-item label="目的仓到仓时间">{{ logisticsDate(current.logistics_dates?.arrived_warehouse_at) }}</el-descriptions-item>
        </el-descriptions>
        <section v-if="current.dispatch_allocations?.length" class="dispatch-allocation-history"><h3>分批集货与物流</h3><article v-for="allocation in current.dispatch_allocations" :key="allocation.batch_id" class="dispatch-allocation"><strong>{{ allocation.batch_number || `批次 ${allocation.batch_id}` }} · {{ logisticsText(allocation.stage) }} · 本批 {{ allocation.quantity }} 件</strong><p>开船：{{ logisticsDate(allocation.logistics_dates?.departed_at) }} · 到港：{{ logisticsDate(allocation.logistics_dates?.arrived_port_at) }} · 到仓：{{ logisticsDate(allocation.logistics_dates?.arrived_warehouse_at) }}</p><ul><li v-for="line in allocation.lines || []" :key="line.shipment_line_id">SKU {{ line.sku || line.sku_code || line.shipment_line_id }} · 本批 {{ line.quantity }} 件</li></ul></article></section>
        <div class="heading"><h3>本次发货商品</h3><el-button v-if="canEdit" @click="addLine">添加 SKU</el-button></div>
        <div class="table-scroll supplier-line-table" :class="{ 'supplier-mode': supplier }"><el-table :data="form.lines" border>
          <el-table-column type="index" label="行" width="55"/><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU / 商品" min-width="210"><template #default="{row}"><el-select v-if="canEdit && !row.id" v-model="row.sku_id" filterable remote reserve-keyword clearable :remote-method="searchShipmentSkus" :loading="skuOptionsLoading" placeholder="搜索 SKU / 商品名" @visible-change="visible=>visible&&loadShipmentOptions()" @change="changeLineSku(row)"><el-option v-for="sku in optionsForRow(row)" :key="sku.id" :label="`${sku.sku_code}${sku.legacy_sku_code ? ` · 旧 ${sku.legacy_sku_code}` : ''} · ${sku.product_name}`" :value="sku.id"/></el-select><DocumentSkuV2 v-if="row.sku_id" :sku="row.sku || row.sku_code" :legacy-sku-code="row.legacy_sku_code"/><small class="sub">{{ row.product_name }}</small></template></el-table-column>
          <el-table-column label="采购量 / 累计已发" min-width="145"><template #default="{row}"><span>{{ purchaseQuantity(row) }} / {{ shippedQuantity(row) }}</span><small class="sub">本次 {{ row.quantity || 0 }} · 超出 {{ excessQuantity(row) }}</small></template></el-table-column>
          <el-table-column label="发货数量" width="140"><template #default="{row}"><el-input-number v-if="canEdit" v-model="row.quantity" :min="1" :precision="0" :controls="false"/><span v-else>{{ row.quantity }}</span></template></el-table-column>
          <el-table-column v-if="!supplier" label="单价" width="150"><template #default="{row}"><el-input-number v-if="canManage && canEdit" v-model="row.unit_price" :min="0" :precision="4" :controls="false"/><el-input-number v-else-if="canPriceEdit && current.status==='submitted'" v-model="row.unit_price" :min="0" :precision="4" :controls="false"/><span v-else>{{ row.unit_price == null ? '待采购补价' : row.unit_price }}</span></template></el-table-column>
          <el-table-column label="超量提示" min-width="140"><template #default="{row}"><el-tag v-if="!purchaseLine(row) && row.sku_id" type="warning">采购单外 SKU</el-tag><el-tag v-else-if="typeof excessQuantity(row)==='number' && excessQuantity(row)>0" type="warning">超出采购 {{ excessQuantity(row) }} 件</el-tag><span v-else class="sub">{{ excessQuantity(row)==='—'?'待确认':'正常' }}</span></template></el-table-column>
          <el-table-column v-if="canEdit" label="操作" width="80"><template #default="{ $index }"><el-button link type="danger" @click="form.lines.splice($index,1)">移除</el-button></template></el-table-column>
        </el-table></div>
        <section v-if="supplier" class="mobile-line-cards" aria-label="本次发货商品">
          <article v-for="(row,index) in form.lines" :key="row.id || `line-${index}`" class="mobile-line-card">
            <div class="mobile-line-heading"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/><div><DocumentSkuV2 v-if="row.sku_id" :sku="row.sku || row.sku_code" :legacy-sku-code="row.legacy_sku_code"/><small v-if="row.product_name" class="sub">{{ row.product_name }}</small><span v-if="!row.sku_id" class="sub">请选择 SKU</span></div></div>
            <el-select v-if="canEdit && !row.id" v-model="row.sku_id" filterable remote reserve-keyword clearable :remote-method="searchShipmentSkus" :loading="skuOptionsLoading" placeholder="搜索 SKU / 商品名" @visible-change="visible=>visible&&loadShipmentOptions()" @change="changeLineSku(row)"><el-option v-for="sku in optionsForRow(row)" :key="sku.id" :label="`${sku.sku_code}${sku.legacy_sku_code ? ` · 旧 ${sku.legacy_sku_code}` : ''} · ${sku.product_name}`" :value="sku.id"/></el-select>
            <div class="mobile-line-quantities"><span>采购 {{ purchaseQuantity(row) }}</span><span>已发 {{ shippedQuantity(row) }}</span><label>本次<el-input-number v-if="canEdit" v-model="row.quantity" :min="1" :precision="0" :controls="false"/><b v-else>{{ row.quantity }}</b></label></div>
            <el-tag v-if="!purchaseLine(row) && row.sku_id" type="warning">采购单外 SKU</el-tag><el-tag v-else-if="typeof excessQuantity(row)==='number' && excessQuantity(row)>0" type="warning">超出采购 {{ excessQuantity(row) }} 件</el-tag><span v-else class="sub">{{ excessQuantity(row)==='—'?'待确认':'正常' }}</span>
            <el-button v-if="canEdit" link type="danger" @click="form.lines.splice(index,1)">移除</el-button>
          </article>
          <p v-if="!form.lines.length" class="mobile-empty">暂无商品</p>
        </section>
        <p class="sub">共 {{ totalQty({lines:form.lines}) }} 件。超出采购数量会提示，但不会阻止提交。</p>
        <el-form-item label="箱号文件（保存草稿后上传）"><input ref="fileInput" type="file" accept=".pdf,.xlsx,.csv,.png,.jpg,.jpeg,application/pdf" :disabled="busy || !current.id || current.status!=='draft' || !canEdit" @change="uploadFile"/><p class="sub">请上传包含本次全部箱号的文件；支持 PDF、Excel、CSV、PNG、JPG，最大 10MB。提交前至少上传一份附件。</p></el-form-item>
        <div class="table-scroll attachment-table-scroll"><el-table :data="current.attachments || []" border empty-text="还没有箱号文件"><el-table-column prop="file_name" label="文件名" min-width="210"/><el-table-column label="大小" width="100"><template #default="{row}">{{ formatSize(row.file_size) }}</template></el-table-column><el-table-column prop="sha256" label="校验值" min-width="180"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="download(row)">下载</el-button><el-button v-if="canEdit" link type="danger" :disabled="busy" @click="removeAttachment(row)">移除</el-button></template></el-table-column></el-table></div>
        <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="notice"/>
      </template>
      <template #footer><div class="actions"><el-button @click="open=false" :disabled="busy">关闭</el-button><el-button v-if="canEdit" @click="save" :loading="busy">保存草稿</el-button><el-button v-if="canPriceEdit && current?.status==='submitted'" @click="savePrices" :loading="busy">保存调价</el-button><el-button v-if="canEdit" type="success" :disabled="busy || !current.attachments?.length" @click="act('submit')">提交发货</el-button><el-button v-if="canEdit && current?.id" type="danger" plain :disabled="busy" @click="act('cancel')">作废</el-button><el-button v-if="!supplier && canManage && current?.status==='submitted' && current.delivery_mode!=='factory_loading' && !current.collection_arrived" type="primary" plain :disabled="busy" @click="arrived">标记到仓</el-button></div></template>
    </el-drawer>
  </AppPage>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import AppPage from '../../components/AppPage.vue';
import CostSettlementLinkV2 from '../../components/supply-chain/CostSettlementLinkV2.vue';
import DocumentSkuV2 from '../../components/supply-chain/DocumentSkuV2.vue';
import DocumentProductImageV2 from '../../components/supply-chain/DocumentProductImageV2.vue';
import * as api from '../../api/supplyShipmentsV2';
import { useAuthStore } from '../../stores/auth';

const props = defineProps({ supplier: { type: Boolean, default: false } });
const route = useRoute();
const auth=useAuthStore();
const orders=ref([]), orderTotal=ref(0), orderOffset=ref(0), ordersLoadingMore=ref(false), shipments=ref([]), skus=ref([]), skuOptionsLoading=ref(false), skuSearch=ref(''), orderId=ref(route.query.order_id ? Number(route.query.order_id) : ''), status=ref(''), page=ref(1), limit=ref(20), total=ref(0), loading=ref(false), busy=ref(false), error=ref(''), open=ref(false), current=ref(null), formError=ref(''), fileInput=ref(null), savedPayload=ref('');
const form=reactive({shipment_date:'',delivery_mode:'collection_center',loading_address:'',notes:'',lines:[]});
const priceReason=ref('');
const selectedProgress=ref(null),progressLoading=ref(false),progressError=ref('');let progressRequest=0;
const shipmentTabs=[{value:'',label:'全部'},{value:'draft',label:'待提交'},{value:'submitted',label:'已发货'},{value:'cancelled',label:'已作废'}];
function closeProgress(){++progressRequest;selectedProgress.value=null;progressLoading.value=false;}
function selectShipmentStatus(value){status.value=value;closeProgress();onOrderChange();}
function allocatedQty(row){return (row.dispatch_allocations||[]).reduce((sum,item)=>sum+Number(item.quantity||0),0);}
async function openShipmentProgress(row){const sequence=++progressRequest;selectedProgress.value=row;progressError.value='';progressLoading.value=true;try{const result=unwrap(await api.fetchShipment(row.id,props.supplier));if(sequence===progressRequest)selectedProgress.value=result;}catch(e){if(sequence===progressRequest)progressError.value=e.message||'读取流程失败';}finally{if(sequence===progressRequest)progressLoading.value=false;}}

const selectedOrder=computed(()=>orders.value.find(o=>String(o.id)===String(orderId.value)));
const canManage=computed(()=>props.supplier || (!auth.authorizationStale && auth.hasPermission('supply.v2.manage')));
const canEdit=computed(()=>canManage.value && !!current.value && current.value.status==='draft' && current.value.editable!==false);
const canPriceEdit=computed(()=>!props.supplier && canManage.value && !!current.value && current.value.price_editable!==false);
const dirty=computed(()=>JSON.stringify(payload())!==savedPayload.value);
const pendingKeys=new Map();
let skuOptionsRequest=0;
function unwrap(r){if(!r?.success)throw new Error(r?.message||'请求失败');return r.data;}
function rowsOf(data){return Array.isArray(data)?data:(data?.results||data?.items||data?.rows||[]);}
async function loadOrderPage(reset=false){if(reset){orders.value=[];orderOffset.value=0;}ordersLoadingMore.value=true;try{const response=await api.fetchShipmentOrders(props.supplier,{limit:100,offset:orderOffset.value});orders.value.push(...rowsOf(unwrap(response)).filter(o=>o.status==='confirmed'&&!orders.value.some(old=>String(old.id)===String(o.id))));orderTotal.value=Number(response.count||0);orderOffset.value+=100;return '';}catch(e){const problem=`采购订单加载失败：${e.message||'请求失败'}`;error.value=problem;return problem;}finally{ordersLoadingMore.value=false;}}
async function loadMoreOrders(){if(!ordersLoadingMore.value&&orderOffset.value<orderTotal.value)await loadOrderPage();}
async function load(){error.value='';let routeProblem='';const [orderProblem,shipmentProblem]=await Promise.all([loadOrderPage(true),loadShipments()]);if(orderProblem||shipmentProblem)error.value=orderProblem||shipmentProblem;if(orderId.value&&!orders.value.some(o=>String(o.id)===String(orderId.value))){try{const detail=unwrap(await api.fetchShipmentOrder(orderId.value,props.supplier));if(detail.status==='confirmed')orders.value.unshift(detail);else if(route.query.order_id)routeProblem='链接中的采购订单尚未确认，发货单目前不可见。';}catch(e){if(route.query.order_id)routeProblem=`无法读取指定采购订单：${e.message||'请求失败'}`;}}if(routeProblem)error.value=routeProblem;}
async function loadShipments(){loading.value=true;try{const response=await api.fetchShipments(props.supplier,{limit:limit.value,offset:(page.value-1)*limit.value,...(status.value?{status:status.value}:{}),...(orderId.value?{order_id:orderId.value}:{})});const data=unwrap(response);shipments.value=rowsOf(data);total.value=Number(response.count||0);return '';}catch(e){const problem=`发货单加载失败：${e.message||'请求失败'}`;error.value=problem;return problem;}finally{loading.value=false;}}
function onOrderChange(){closeProgress();page.value=1;loadShipments();}
watch(()=>route.query.order_id,(v)=>{if(v){orderId.value=Number(v);onOrderChange();}});
function statusText(s){return {draft:'草稿',submitted:'已提交',cancelled:'已作废'}[s]||s;}
function logisticsText(s){return {unmarked:'未标记',departed:'开船',arrived_port:'到港',arrived_warehouse:'到仓',split:'分批运输'}[s]||'未标记';}
function shipmentLogisticsText(row){const allocations=row.dispatch_allocations||[];if(!allocations.length)return logisticsText(row.logistics_stage);return `${allocations.length} 个批次 · ${allocations.map(item=>logisticsText(item.stage)).join(' / ')}`;}
function logisticsDate(value){return value?new Date(value).toLocaleString():'未记录';}
function totalQty(s){return (s.lines||[]).reduce((n,l)=>n+Number(l.quantity||0),0);}
function cleanLine(l){return { ...(l.id?{id:l.id}:{}),sku_id:l.sku_id, purchase_line_id:l.purchase_line_id??null,quantity:Number(l.quantity), ...(!props.supplier?{unit_price:l.unit_price==null||l.unit_price===''?null:Number(l.unit_price)}:{})};}
function payload(){return {shipment_date:form.shipment_date,delivery_mode:form.delivery_mode,...(form.delivery_mode==='factory_loading'?{loading_address:form.loading_address}:{}),notes:form.notes,lines:form.lines.map(cleanLine)};}
function editForm(s){current.value=s;Object.assign(form,{shipment_date:s.shipment_date||today(),delivery_mode:s.delivery_mode||'collection_center',loading_address:s.loading_address||'',notes:s.notes||'',lines:(s.lines||[]).map(l=>({...l,quantity:Number(l.quantity),unit_price:l.unit_price==null?null:Number(l.unit_price)}))});savedPayload.value=JSON.stringify(payload());formError.value='';}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function mutate(slot,data,execute){const fingerprint=JSON.stringify(data);let pending=pendingKeys.get(slot);if(!pending||pending.fingerprint!==fingerprint){pending={fingerprint,key:api.createIdempotencyKey()};pendingKeys.set(slot,pending);}return execute(pending.key).then(response=>{const result=unwrap(response);pendingKeys.delete(slot);return result;});}
function mergeSnapshot(data){if(!data)return;current.value={...current.value,...data};}
async function newShipment(){if(!canManage.value||busy.value||!selectedOrder.value)return;busy.value=true;try{const order=unwrap(await api.fetchShipmentOrder(selectedOrder.value.id,props.supplier));if(order.status!=='confirmed')throw new Error('只有已确认采购单可以新建发货单。');const lines=(order.lines||[]).map(l=>{const qty=Number(l.quantity),shipped=Number(l.shipped_quantity),unshipped=l.unshipped_quantity!=null?Number(l.unshipped_quantity):Number.isFinite(shipped)?Math.max(0,qty-shipped):null;return {line:l,unshipped};}).filter(item=>Number.isFinite(item.unshipped)&&item.unshipped>0).map(({line:l,unshipped})=>({sku_id:l.sku_id,sku:l.sku,legacy_sku_code:l.legacy_sku_code||'',image_preview_url:l.image_preview_url||l.product_details?.image_url||'',product_name:l.product_name||l.name,purchase_line_id:l.id,quantity:unshipped,unit_price:l.unit_price==null?null:Number(l.unit_price)}));editForm({id:null,order_id:order.id,order_number:order.number,status:'draft',version:0,attachments:[],lines});open.value=true;loadShipmentOptions('');}catch(e){error.value=e.message||'读取采购订单失败';}finally{busy.value=false;}}
async function openShipment(row){busy.value=true;try{const shipment=unwrap(await api.fetchShipment(row.id,props.supplier));if(shipment.order_id&&!orders.value.some(order=>String(order.id)===String(shipment.order_id))){try{const order=unwrap(await api.fetchShipmentOrder(shipment.order_id,props.supplier));if(order.status==='confirmed')orders.value.unshift(order);}catch{}}editForm(shipment);open.value=true;}catch(e){error.value=e.message||'读取发货单失败';}finally{busy.value=false;}}
function optionsForRow(row){const list=[...skus.value];if(row.sku_id&&!list.some(s=>String(s.id)===String(row.sku_id)))list.unshift({id:row.sku_id,sku_code:row.sku||row.sku_code||String(row.sku_id),legacy_sku_code:row.legacy_sku_code||'',product_name:row.product_name||''});return list;}
async function loadShipmentOptions(search=skuSearch.value){skuSearch.value=search||'';const request=++skuOptionsRequest;skuOptionsLoading.value=true;try{const response=unwrap(await api.fetchShipmentOptions(props.supplier,{search:skuSearch.value,limit:50,offset:0}));if(request===skuOptionsRequest)skus.value=Array.isArray(response)?response:(response?.skus||[]);}catch(e){if(request===skuOptionsRequest)formError.value=`SKU 选项加载失败：${e.message||'请求失败'}`;}finally{if(request===skuOptionsRequest)skuOptionsLoading.value=false;}}
function searchShipmentSkus(query){loadShipmentOptions(query);}
function changeLineSku(row){const sources=(selectedOrder.value?.lines||[]).filter(l=>String(l.sku_id)===String(row.sku_id));row.purchase_line_id=sources.length===1?sources[0].id:null;const sku=skus.value.find(s=>String(s.id)===String(row.sku_id));row.sku=sku?.sku_code;row.legacy_sku_code=sku?.legacy_sku_code||'';row.image_preview_url=sku?.image_preview_url||'';row.product_name=sku?.product_name;row.unit_price=sources.length===1&&sources[0].unit_price!=null?Number(sources[0].unit_price):null;}
function purchaseLine(row){const sourceOrder=orders.value.find(order=>String(order.id)===String(current.value?.order_id))||selectedOrder.value;return (sourceOrder?.lines||[]).find(l=>String(l.id)===String(row.purchase_line_id))||(sourceOrder?.lines||[]).find(l=>String(l.sku_id)===String(row.sku_id));}
function purchaseQuantity(row){const line=purchaseLine(row);return line?.quantity??'—';}
function shippedQuantity(row){const line=purchaseLine(row);return line?.shipped_quantity??'—';}
function excessQuantity(row){const line=purchaseLine(row);if(!line)return row.sku_id?'采购单外 SKU':0;const purchased=Number(line.quantity),shipped=line.shipped_quantity!=null?Number(line.shipped_quantity):line.unshipped_quantity!=null?Math.max(0,Number(line.quantity)-Number(line.unshipped_quantity)):NaN;if(!Number.isFinite(purchased)||!Number.isFinite(shipped))return '—';const sourceId=String(line.id);const submitted= form.lines.filter(item=>String(item.purchase_line_id)===sourceId).reduce((sum,item)=>sum+Number(item.quantity||0),0);return Math.max(0,shipped+submitted-purchased);}
function addLine(){if(canEdit.value){form.lines.push({sku_id:null,purchase_line_id:null,quantity:1,unit_price:null});loadShipmentOptions('');}}
async function save(){if(!canEdit.value||busy.value)return false;formError.value='';if(!form.shipment_date||!form.lines.length||form.lines.some(l=>!l.sku_id||!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1)){formError.value='请填写发货日期，并为每行选择 SKU 和大于 0 的整数数量。';return false;}busy.value=true;try{const data={...payload(),...(current.value.id?{expected_version:current.value.version}:{order_id:current.value.order_id})};const result=await mutate(`save-${current.value.id||'new'}`,data,key=>current.value.id?api.updateShipment(current.value.id,data,props.supplier,key):api.createShipment(data,props.supplier,key));editForm(result);ElMessage.success('发货草稿已保存。');await loadShipments();return true;}catch(e){formError.value=e.message||'保存失败，草稿内容已保留。';return false;}finally{busy.value=false;}}
async function savePrices(){if(!canPriceEdit.value||busy.value)return;if(form.lines.some(l=>l.unit_price==null||l.unit_price===''||!Number.isFinite(Number(l.unit_price))||Number(l.unit_price)<0)){formError.value='请为每行填写大于或等于 0 的有效单价。';return;}if(current.value.price_adjustment_requires_reason&&!priceReason.value.trim()){formError.value='已集货的发货单调价必须填写原因。';return;}busy.value=true;formError.value='';try{const lines=form.lines.map(l=>({id:l.id,unit_price:Number(l.unit_price)})),data={expected_version:current.value.version,lines,...(priceReason.value.trim()?{reason:priceReason.value.trim()}:{})};const result=await mutate(`prices-${current.value.id}`,data,key=>api.updateShipmentPrices(current.value.id,data,key));editForm(result);priceReason.value='';ElMessage.success('价格已保存。');await loadShipments();}catch(e){formError.value=e.message||'调价失败';}finally{busy.value=false;}}
function onCostUpdated(target){if(target&&current.value&&String(target.id)===String(current.value.id))current.value={...current.value,...target};}
async function act(action){if(!current.value||!canManage.value&&action==='cancel')return;if(action==='submit'&&dirty.value&&!await save())return;if(action==='submit'&&current.value.delivery_mode==='factory_loading'&&!String(current.value.loading_address||'').trim()){formError.value='货柜上门装载的发货单提交前必须填写装柜地址。';return;}try{await ElMessageBox.confirm(action==='submit'?'提交后供应商发货信息将进入采购协同。':'作废这张发货单？',action==='submit'?'提交发货':'作废发货单',{type:'warning'});}catch{return;}busy.value=true;try{const body={expected_version:current.value.version};const result=await mutate(`${action}-${current.value.id}`,body,key=>action==='submit'?api.submitShipment(current.value.id,body,props.supplier,key):api.cancelShipment(current.value.id,body,props.supplier,key));editForm(result);await loadShipments();ElMessage.success(action==='submit'?'发货单已提交。':'发货单已作废。');}catch(e){formError.value=e.message||'操作失败';}finally{busy.value=false;}}
async function arrived(){if(props.supplier||!canManage.value||busy.value)return;busy.value=true;try{const body={expected_version:current.value.version};editForm(await mutate(`arrival-${current.value.id}`,body,key=>api.markShipmentArrived(current.value.id,body,key)));await loadShipments();ElMessage.success('已标记到仓。');}catch(e){formError.value=e.message||'标记到仓失败';}finally{busy.value=false;}}
async function uploadFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>10*1024*1024||! /\.(pdf|xlsx|csv|png|jpe?g)$/i.test(file.name)){formError.value='请选择 10MB 以内的 PDF、XLSX、CSV、PNG 或 JPG 文件。';return;}if(!canEdit.value)return;if(dirty.value&&!await save())return;if(!current.value?.id){formError.value='请先保存发货草稿，再上传箱号文件。';return;}busy.value=true;try{const version=current.value.version,result=await mutate(`upload-${current.value.id}-${file.name}`,{version,name:file.name,size:file.size,modified:file.lastModified},key=>api.uploadShipmentAttachment(current.value.id,file,version,props.supplier,key));mergeSnapshot(result);formError.value='';}catch(e){formError.value=e.message||'上传失败';}finally{busy.value=false;}}
async function removeAttachment(a){if(!canEdit.value)return;try{await ElMessageBox.confirm(`移除附件“${a.file_name}”？`,'移除附件',{type:'warning'});}catch{return;}busy.value=true;try{const body={expected_version:current.value.version};const result=await mutate(`remove-${current.value.id}-${a.id}`,body,key=>api.removeShipmentAttachment(current.value.id,a.id,body,props.supplier,key));mergeSnapshot(result);}catch(e){formError.value=e.message||'移除失败';}finally{busy.value=false;}}
async function download(a){const r=await api.downloadShipmentAttachment(current.value.id,a.id,a.file_name,props.supplier);if(!r?.success)formError.value=r?.message||'下载失败';}
function formatSize(n){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;}
function closeDrawer(done){if(!busy.value)done();}
defineExpose({savePrices,priceReason,current,form,formError});
onMounted(load);
</script>

