idth:0}.shipment-timeline .node{display:flex;align-items:center;justify-content:center;flex:none;width:26px;height:26px;border-radius:50%;background:#e4eaf3;color:#617087;font-weight:600}.shipment-timeline li.reached .node{background:#2563eb;color:white}.shipment-timeline li:not(:last-child):after{content:'';position:absolute;top:12px;left:55%;right:-12px;height:1px;background:#d9e2f0}.shipment-timeline b{display:inline-block;margin-right:8px;line-height:26px}.shipment-timeline p{font-size:12px;color:#64748b;margin:6px 0 0}.shipment-related{display:grid;grid-template-columns:minmax(0,3fr) minmax(220px,1fr);gap:12px}.related-docs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid #e3eaf5;border-radius:5px;padding:14px;gap:18px}.related-docs b,.related-docs a,.related-docs span{display:block;font-size:12px;line-height:1.8;overflow-wrap:anywhere}.related-docs b{font-size:11px;color:#475569;margin-bottom:5px}.related-docs a{color:#2563eb}.related-docs span{color:#64748b}.next-action{background:#f4f7fc;padding:12px 16px;border-radius:5px;font-size:12px;color:#334155}.dispatch-next-link{display:block;margin:10px 0 0;color:#2563eb;font-size:12px}.next-action p{font-size:12px;color:#64748b;line-height:1.6;margin:6px 0 10px}@media(max-width:680px){.shipment-timeline,.shipment-related,.related-docs{grid-template-columns:1fr}.shipment-timeline li:after{display:none}.shipment-progress-panel>header p span{display:block;margin:5px 0}.shipment-workbench :deep(.app-page__header){flex-wrap:wrap}}
